package com.github.dcysteine.nesql.exporter.capture;

import codechicken.nei.recipe.*;
import com.github.dcysteine.nesql.exporter.source.*;
import com.github.dcysteine.nesql.exporter.task.Jobs;
import com.google.gson.*;
import forestry.api.recipes.*;
import forestry.api.fuels.*;
import net.minecraft.init.Items;
import net.minecraft.item.*;
import net.minecraft.inventory.*;
import net.minecraftforge.fluids.*;
import net.minecraftforge.oredict.OreDictionary;
import java.util.*;
import static com.github.dcysteine.nesql.exporter.capture.MagicApi.*;
import static com.github.dcysteine.nesql.exporter.source.Json.*;

/** Forestry 4.10.17: owned native state-machine rules, never bulk guaranteed yields. */
final class ForestryProcessingRecipes implements RegistryRecipes {
    private static final String PREFIX="forestry.factory.recipes.";
    private final String machine,program,signature;
    private final Bundle rules;
    private final JsonObject context;
    private final ForestryRecipeBindings bindings;
    private final Map<String,NativeItemVariants> variants=new LinkedHashMap<>();
    private boolean closed;
    private final List<int[]> pages=new ArrayList<>();
    private final Set<Facts> published=Collections.newSetFromMap(new IdentityHashMap<Facts,Boolean>());
    static boolean supportsClass(String name){return name!=null&&(name.equals(PREFIX+"nei.NEIHandlerFermenter")||name.equals(PREFIX+"nei.NEIHandlerMoistener")||name.equals(PREFIX+"nei.NEIHandlerCarpenter"));}
    static boolean supports(ICraftingHandler handler){return handler!=null&&supportsClass(handler.getClass().getName());}
    ForestryProcessingRecipes(TemplateRecipeHandler handler){
        MagicApi.version("ForestryProcessingRecipes","Forestry");if(!supports(handler))throw fault("Unadapted Forestry processing handler");
        bindings=new ForestryRecipeBindings(handler.getClass());
        machine=handler.getClass().getSimpleName().substring("NEIHandler".length()).toLowerCase(Locale.ROOT);rules=read();context=rules.json();signature=CanonicalJson.digest(context);program=Identity.content("program",object("kind","forestryProcessing","rules",context));
        if(machine.equals("fermenter"))for(int i=0;i<rules.fermenter.size();i++)for(int v=0;v<rules.fermenter.get(i).variations.size();v++)pages.add(new int[]{i,v});
        else if(machine.equals("moistener"))for(int i=0;i<rules.moistener.size();i++)for(int fuel=0;fuel<rules.moistenerFuels.size();fuel++)pages.add(new int[]{i,fuel});
        else for(int i=0;i<rules.carpenter.size();i++)pages.add(new int[]{i,-1});verify();
    }
    public int size(){alive();return pages.size();}
    public void verify(){alive();bindings.verifyRoots();}
    public void finishVerification(){verify();bindings.verify();if(!signature.equals(CanonicalJson.digest(read().json())))throw new Jobs.Fault("recipe_changed","Forestry processing registry, callback, ore or difficulty changed");for(NativeItemVariants source:variants.values())source.verify();}
    public String program(Facts facts){verify();if(published.add(facts))for(String section:new String[]{"fermenter","fermenterFuels","moistener","moistenerFuels","carpenter"})chunks(facts,section,context.getAsJsonArray(section));return program;}
    private void chunks(Facts facts,String section,JsonArray source){JsonArray rows=array();int offset=0,bytes=0;for(JsonElement value:source){Jobs.checkpoint();int size=CanonicalJson.bytes(value).length;if(size>900000)throw fault("Forestry processing rule exceeds row budget");if(rows.size()==128||bytes+size>900000){chunk(facts,section,offset,rows);offset+=rows.size();rows=array();bytes=0;}rows.add(owned(value));bytes+=size;}if(rows.size()>0||source.size()==0)chunk(facts,section,offset,rows);}
    private void chunk(Facts facts,String section,int offset,JsonArray rows){String kind="forestry"+Character.toUpperCase(section.charAt(0))+section.substring(1);JsonObject row=object("program",program,"offset",offset,"data",object("kind",kind,"rows",rows));row.addProperty("id",program+"."+Identity.content("chunk",row));facts.row("programs",row);}
    public boolean capture(int index,RecipeRow row){alive();if(index<0||index>=pages.size())throw new IndexOutOfBoundsException("Forestry processing recipe "+index);int[] page=pages.get(index);int selector=page[0];
        row.record.add("process",object("kind","forestryProcessing","program",program,"machine",machine,"selector",selector,"fuel",machine.equals("moistener")?page[1]:null,"variation",machine.equals("fermenter")?page[1]:null));
        if(machine.equals("fermenter"))ferment(rules.fermenter.get(selector),page[1],row);else if(machine.equals("moistener"))moisten(rules.moistener.get(selector),rules.moistenerFuels.get(page[1]),row);else return carpentry(rules.carpenter.get(selector),row);return true;
    }
    private void ferment(Ferment recipe,int variation,RecipeRow row){Variation sample=recipe.variations.get(variation);
        List<RecipeRow.Ingredient> inputs=choices(sample.resource,false);for(RecipeRow.Ingredient input:inputs){input.rule.addProperty("meta",recipe.resource.getItemDamage()==32767);input.rule.addProperty("nbt",recipe.resource.getTagCompound()==null||recipe.resource.getTagCompound().hasNoTags());}row.itemInput(0,inputs,false);
        FluidStack demand=recipe.fluid.copy();demand.amount=1;row.fluidInput(0,demand,false);allocated(row.inputs.get(row.inputs.size()-1).getAsJsonObject());
        // Nonpositive fuel rates cannot pass StandardTank.canDrain. For a
        // positive resource value there are at most value positive-rate steps.
        // Negative values can wrap after subtraction; keep their signed facts
        // and use INT_MAX+1 steps as a conservative bound. Each step is 10k max.
        // NEI's bulk preview is not an attainable production upper bound.
        FluidStack output=new FluidStack(recipe.output,1);JsonObject quantity=potential("fermenter",1);quantity.addProperty("nominal",Long.toString((recipe.value>0?(long)recipe.value:(long)Integer.MAX_VALUE+1L)*10000L));row.fluidOutput(0,output,quantity);
        row.note("forestry:fermenter", "forestry.factory.tiles.TileFermenter#workCycle", row.facts.locale().equals("zh_CN")?"每份原料有 "+recipe.value+" 发酵单位。基础每步工作 4 个供能 tick、能量参数 4200 RF；难度、升级、燃料、流体空间与状态转换共同决定实际产出，不能将预览数量视为保证产量。":"Each resource has "+recipe.value+" fermentation units. A base step uses 4 powered ticks and a 4200 RF energy parameter; difficulty, upgrades, fuel, tank space and state transitions govern completion. The preview is not a guaranteed yield.");
    }
    private void moisten(Moisten recipe,MoistFuel fuel,RecipeRow row){
        row.itemInput(0,choices(recipe.resource,false),false);
        row.itemInput(1,choices(fuel.item,false),false);allocated(row.inputs.get(row.inputs.size()-1).getAsJsonObject());
        row.fluidInput(0,new FluidStack(FluidRegistry.WATER,1),false,object("kind","wildcard","meta",false,"nbt",true));allocated(row.inputs.get(row.inputs.size()-1).getAsJsonObject());
        row.itemOutput(0,recipe.product,10000,potential("moistener",recipe.product.stackSize));
        if(fuel.product!=null)row.itemOutput(1,fuel.product,10000,potential("moistenerFuel",fuel.product.stackSize));
        row.note("forestry:moistener", "forestry.factory.tiles.TileMoistener#workCycle", row.facts.locale().equals("zh_CN")?"每份资源生产计时单位为 "+recipe.time+"；仅方块亮度不超过 11 时运行。原料、工作燃料、水与输出空间需通过完整原生状态转换后才产生结果。":"Production timer units per resource: "+recipe.time+". Operation requires block light at most 11. Resource, working material, water and output space must pass the native state transitions before results are produced.");
    }
    private boolean carpentry(Carpentry recipe,RecipeRow row){for(Object ingredient:recipe.grid.ingredients)if(ingredient instanceof List&&((List<?>)ingredient).isEmpty())return false;
        int slot=0;
        if(recipe.box!=null)row.itemInput(slot++,choices(recipe.box,false),false);
        JsonArray cells=array();for(int cell=0;cell<recipe.grid.ingredients.length;cell++){Object ingredient=recipe.grid.ingredients[cell];if(ingredient==null){cells.add(value(null));continue;}List<RecipeRow.Ingredient> choices=new ArrayList<>();for(ItemStack item:members(ingredient))choices.addAll(choices(item,false));if(choices.isEmpty())return false;cells.add(value(slot));row.itemInput(slot++,choices,false);allocated(row.inputs.get(row.inputs.size()-1).getAsJsonObject());}
        if(recipe.fluid!=null)row.fluidInput(0,recipe.fluid,false);row.itemOutput(0,recipe.grid.result,10000,potential("carpenter",recipe.grid.result.stackSize));
        row.record.add("grid",object("width",recipe.grid.width,"height",recipe.grid.height,"cells",cells,"mirror",true));row.note("forestry:carpenter", "forestry.factory.tiles.TileCarpenter#workCycle", row.facts.locale().equals("zh_CN")?"基础包装工作量 "+recipe.time+"，基础循环能量参数 "+(recipe.time*204)+" RF；难度与升级可改变实际用能／时间。保留原生匹配网格、空位、包装物与库存分配；显示的是完成条件满足后的潜在产物。":"Base packaging work: "+recipe.time+"; base cycle energy parameter: "+(recipe.time*204)+" RF. Difficulty and upgrades alter actual energy/time. The native matrix, empty cells, packaging and stock allocation are retained; results are conditional on completion.");return true;
    }
    public JsonObject exclusion(int index){if(machine.equals("carpenter")){Object[] ingredients=rules.carpenter.get(pages.get(index)[0]).grid.ingredients;for(int i=0;i<ingredients.length;i++)if(ingredients[i] instanceof List&&((List<?>)ingredients[i]).isEmpty())return object("kind","forestry-carpenter-unreachable","reason","empty native ingredient OR list never matches","cell",i);}return null;}
    private Bundle read(){Bundle result=new Bundle();if(machine.equals("fermenter")){for(Object raw:registry("Fermenter")){exact(raw,"FermenterRecipe");result.fermenter.add(new Ferment((IFermenterRecipe)raw));}for(Map.Entry<?,?> entry:fuelMap("fermenterFuel").entrySet())result.fermenterFuels.add(new FermentFuel(entry.getKey(),(FermenterFuel)entry.getValue()));}
        else if(machine.equals("moistener")){for(Object raw:registry("Moistener")){exact(raw,"MoistenerRecipe");result.moistener.add(new Moisten((IMoistenerRecipe)raw));}for(Map.Entry<?,?> entry:fuelMap("moistenerResource").entrySet())result.moistenerFuels.add(new MoistFuel(entry.getKey(),(MoistenerFuel)entry.getValue()));}
        else for(Object raw:registry("Carpenter")){exact(raw,"CarpenterRecipe");result.carpenter.add(new Carpentry((ICarpenterRecipe)raw));}return result;}
    private static Collection<?> registry(String kind){Object registry=field(type(PREFIX+kind+"RecipeManager"),null,"recipes");if(!(registry instanceof Set)||((Set<?>)registry).size()>262144)throw fault("Invalid Forestry processing registry");return (Collection<?>)registry;}
    private static Map<?,?> fuelMap(String name){Object registry=field(type("forestry.api.fuels.FuelManager"),null,name);if(registry==null||!registry.getClass().getName().equals("forestry.core.utils.datastructures.ItemStackMap")||((Map<?,?>)registry).size()>65536)throw fault("Unadapted Forestry fuel map");return (Map<?,?>)registry;}
    private static JsonObject potential(String name,int nominal){return object("kind","potential","stat","forestry:"+name+"Completion","condition","Native processing state, fuel, stock, tank and output-space transitions must complete","nominal",Integer.toString(Math.max(1,nominal)));}
    private static void allocated(JsonObject input){for(JsonElement raw:input.getAsJsonArray("choices"))raw.getAsJsonObject().add("consume",object("kind","allocated"));}
    private List<RecipeRow.Ingredient> choices(ItemStack source,boolean keep){ItemStack template=item(source);template.stackSize=1;ItemStack[] expanded;if(template.getItemDamage()==32767){String key=Item.itemRegistry.getNameForObject(template.getItem());if(key==null)throw fault("Unregistered Forestry wildcard item");NativeItemVariants candidates=variants.get(key);if(candidates==null){candidates=new NativeItemVariants(template);variants.put(key,candidates);}expanded=candidates.copies();}else expanded=new ItemStack[]{template};List<RecipeRow.Ingredient> values=new ArrayList<>();for(ItemStack variant:expanded){ItemStack copy=variant.copy();copy.setTagCompound(template.getTagCompound()==null?null:(net.minecraft.nbt.NBTTagCompound)template.getTagCompound().copy());values.add(new RecipeRow.Ingredient(copy,1,keep,object("kind","wildcard","meta",template.getItemDamage()==32767,"nbt",template.getTagCompound()==null||template.getTagCompound().hasNoTags())));}return values;}
    private void alive(){Jobs.checkpoint();if(closed)throw new Jobs.Fault("capture_closed","Forestry processing reader is closed");}
    public void close(){if(closed)return;closed=true;bindings.close();pages.clear();variants.clear();published.clear();rules.fermenter.clear();rules.fermenterFuels.clear();rules.moistener.clear();rules.moistenerFuels.clear();rules.carpenter.clear();}
    private static List<ItemStack> members(Object value){if(value instanceof ItemStack)return Collections.singletonList(item((ItemStack)value));if(!(value instanceof ArrayList)||((List<?>)value).size()>65536)throw fault("Unadapted Forestry grid ingredient");List<ItemStack> result=new ArrayList<>();for(Object raw:(List<?>)value){if(!(raw instanceof ItemStack))throw fault("Invalid Forestry ingredient member");result.add(item((ItemStack)raw));}return result;}
    private static ItemStack item(ItemStack item){if(item==null||item.getClass()!=ItemStack.class||item.getItem()==null||item.stackSize<=0)throw fault("Invalid Forestry processing item");NativeStackAudit.audit(item);return item.copy();}
    private static FluidStack liquid(FluidStack fluid){if(fluid==null||fluid.getClass()!=FluidStack.class||fluid.getFluid()==null||fluid.amount<=0)throw fault("Invalid Forestry processing fluid");return fluid.copy();}
    private static JsonObject stack(ItemStack source){if(source==null)return null;ItemStack copy=item(source);JsonObject result=SqueezerRules.stack(copy);result.addProperty("subtypes",copy.getHasSubtypes());result.addProperty("maxDamage",copy.getMaxDamage());result.addProperty("containerOwner",ItemCallbacks.method(copy.getItem(),"getContainerItem","getContainerItem",ItemStack.class).getDeclaringClass().getName());if(!ItemCallbacks.hasContainer(copy))result.add("container",object("kind","none"));else{ItemStack returned=ItemCallbacks.container(copy,copy.getItemDamage()==32767);if(ItemCallbacks.method(copy.getItem(),"doesContainerItemLeaveCraftingGrid","doesContainerItemLeaveCraftingGrid",ItemStack.class).getDeclaringClass()!=Item.class)throw fault("Unadapted native container stow callback");JsonObject descriptor=SqueezerRules.stack(returned);descriptor.addProperty("subtypes",returned.getHasSubtypes());descriptor.addProperty("maxDamage",returned.getMaxDamage());result.add("container",object("kind","fixed","result",descriptor,"leave",copy.getItem().doesContainerItemLeaveCraftingGrid(copy.copy())));}return result;}
    private static JsonObject fluid(FluidStack source){if(source==null)return null;FluidStack copy=liquid(source);return object("registry",copy.getFluid().getName(),"amount",copy.amount,"nbt",TypedNbt.encode(copy.tag),"viscosity",copy.getFluid().getViscosity(copy));}
    private static JsonObject key(Object raw){if(raw instanceof ItemStack)return object("kind","stack","stack",stack((ItemStack)raw));if(raw instanceof Item)return object("kind","item","registry",Item.itemRegistry.getNameForObject(raw));if(raw instanceof String){JsonArray members=array();for(ItemStack member:OreDictionary.getOres((String)raw))members.add(stack(member));return object("kind","ore","members",members);}throw fault("Unknown native Forestry fuel key");}
    private static String bits(float value){return String.format(Locale.ROOT,"%08x",Float.floatToRawIntBits(value));}
    private static String difficulty(){Object mode=field(type("forestry.api.core.ForestryAPI"),null,"activeMode");return mode==null?bits(1f):bits((Float)invoke(mode.getClass(),mode,"getFloatSetting",new Class<?>[]{String.class},"energy.demand.modifier"));}
    private static JsonElement owned(JsonElement value){return value==null?JsonNull.INSTANCE:new JsonParser().parse(value.toString());}
    private static void exact(Object source,String kind){if(source==null||!source.getClass().getName().equals(PREFIX+kind))throw fault("Unadapted Forestry processing implementation");}
    private static Jobs.Fault fault(String message){return new Jobs.Fault("recipe_unsupported",message);}
    private interface Rule{JsonObject json();}
    private static final class Bundle{final List<Ferment> fermenter=new ArrayList<>();final List<FermentFuel> fermenterFuels=new ArrayList<>();final List<Moisten> moistener=new ArrayList<>();final List<MoistFuel> moistenerFuels=new ArrayList<>();final List<Carpentry> carpenter=new ArrayList<>();JsonObject json(){JsonObject result=object("fermenter",json(fermenter),"fermenterFuels",json(fermenterFuels),"moistener",json(moistener),"moistenerFuels",json(moistenerFuels),"carpenter",json(carpenter));if(CanonicalJson.bytes(result).length>16*1024*1024)throw fault("Forestry processing rules exceed 16MiB");return result;}private JsonArray json(List<? extends Rule> values){JsonArray array=array();for(Rule rule:values){Jobs.checkpoint();array.add(rule.json());}return array;}}
    private static final class Variation implements Rule{final ItemStack resource;final float modifier;Variation(ItemStack resource){this.resource=item(resource);modifier=resource.getItem() instanceof IVariableFermentable?((IVariableFermentable)resource.getItem()).getFermentationModifier(resource.copy()):1f;}public JsonObject json(){return object("resource",stack(resource),"modifier",bits(modifier));}}
    private static final class Ferment implements IFermenterRecipe,Rule{final ItemStack resource;final FluidStack fluid;final int value;final float modifier;final Fluid output;final String difficulty;final boolean variable;final List<Variation> variations=new ArrayList<>();
        Ferment(IFermenterRecipe source){resource=item(source.getResource());fluid=liquid(source.getFluidResource());value=source.getFermentationValue();modifier=source.getModifier();output=source.getOutput();difficulty=difficulty();if(output==null||FluidRegistry.getFluid(output.getName())!=output)throw fault("Unregistered fermentation output");variable=resource.getItem() instanceof IVariableFermentable;if(variable){try{if(!resource.getItem().getClass().getMethod("getFermentationModifier",ItemStack.class).getDeclaringClass().getName().equals("forestry.arboriculture.items.ItemGermlingGE"))throw fault("Unadapted variable fermentation callback");}catch(NoSuchMethodException failure){throw fault("Missing fermentation callback");}@SuppressWarnings("unchecked")List<ItemStack> samples=(List<ItemStack>)invoke(type("forestry.core.recipes.nei.NEIUtils"),null,"getItemVariations",new Class<?>[]{ItemStack.class},resource.copy());if(samples.size()>65536)throw fault("Fermentation variations exceed budget");for(ItemStack sample:samples)variations.add(new Variation(sample));}else variations.add(new Variation(resource));}
        public JsonObject json(){JsonArray samples=array();for(Variation sample:variations)samples.add(sample.json());return object("resource",stack(resource),"fluid",fluid(fluid),"fermentationValue",value,"modifier",bits(modifier),"output",output.getName(),"resourceModifier",object("kind",variable?"treeSappiness":"constant"),"variations",samples,"difficulty",difficulty);}
        public ItemStack getResource(){return resource.copy();}public FluidStack getFluidResource(){return fluid.copy();}public int getFermentationValue(){return value;}public float getModifier(){return modifier;}public Fluid getOutput(){return output;}}
    private static final class FermentFuel implements Rule{final JsonObject key;final ItemStack item;final int rate,duration;FermentFuel(Object key,FermenterFuel source){if(source.getClass()!=FermenterFuel.class)throw fault("Unadapted fermenter fuel");this.key=key(key);item=item(source.item);rate=source.fermentPerCycle;duration=source.burnDuration;}public JsonObject json(){return object("key",owned(key),"item",stack(item),"fermentPerCycle",rate,"burnDuration",duration);}}
    private static final class Moisten implements IMoistenerRecipe,Rule{final ItemStack resource,product;final int time;Moisten(IMoistenerRecipe source){resource=item(source.getResource());product=item(source.getProduct());time=source.getTimePerItem();}public JsonObject json(){return object("resource",stack(resource),"product",stack(product),"timePerItem",time);}public ItemStack getResource(){return resource.copy();}public ItemStack getProduct(){return product.copy();}public int getTimePerItem(){return time;}}
    private static final class MoistFuel implements Rule{final JsonObject key;final ItemStack item,product;final int stage,value;MoistFuel(Object key,MoistenerFuel source){if(source.getClass()!=MoistenerFuel.class)throw fault("Unadapted moistener fuel");this.key=key(key);item=item(source.item);product=source.product==null?null:item(source.product);stage=source.stage;value=source.moistenerValue;}MoistenerFuel nativeFuel(){return new MoistenerFuel(item.copy(),product==null?null:product.copy(),stage,value);}public JsonObject json(){return object("key",owned(key),"item",stack(item),"product",stack(product),"stage",stage,"moistenerValue",value);}}
    private static final class Carpentry implements ICarpenterRecipe,Rule{final ItemStack box;final FluidStack fluid;final Grid grid;final int time;final String difficulty;Carpentry(ICarpenterRecipe source){box=source.getBox()==null?null:item(source.getBox());fluid=source.getFluidResource()==null?null:liquid(source.getFluidResource());grid=new Grid(source.getCraftingGridRecipe());time=source.getPackagingTime();difficulty=difficulty();}public JsonObject json(){JsonArray ingredients=array();TreeMap<String,JsonObject> stock=new TreeMap<>();for(Object ingredient:grid.ingredients){if(ingredient==null){ingredients.add(value(null));continue;}JsonArray alternatives=array();for(ItemStack member:members(ingredient)){JsonObject descriptor=stack(member);alternatives.add(descriptor);stock.put(CanonicalJson.digest(descriptor),descriptor);for(int id:OreDictionary.getOreIDs(member))for(ItemStack ore:OreDictionary.getOres(OreDictionary.getOreName(id))){JsonObject candidate=stack(ore);stock.put(CanonicalJson.digest(candidate),candidate);if(stock.size()>65536)throw fault("Carpenter stock alternatives exceed budget");}}ingredients.add(ingredient instanceof ItemStack?alternatives.get(0):alternatives);}JsonArray stockItems=array();for(JsonObject value:stock.values())stockItems.add(value);return object("width",grid.width,"height",grid.height,"box",stack(box),"ingredients",ingredients,"fluid",fluid(fluid),"result",stack(grid.result),"stockItems",stockItems,"packagingTime",time,"difficulty",difficulty);}public ItemStack getBox(){return box==null?null:box.copy();}public FluidStack getFluidResource(){return fluid==null?null:fluid.copy();}public IDescriptiveRecipe getCraftingGridRecipe(){return grid;}public int getPackagingTime(){return time;}}
    private static final class Grid implements IDescriptiveRecipe{final int width,height;final ItemStack result;final Object[] ingredients;Grid(IDescriptiveRecipe source){if(!source.getClass().getName().equals("forestry.core.recipes.ShapedRecipeCustom"))throw fault("Unadapted Carpenter grid callback");width=source.getWidth();height=source.getHeight();result=item(source.getRecipeOutput());Object[] raw=source.getIngredients();if(width<1||width>3||height<1||height>3||raw==null||raw.length!=width*height)throw fault("Invalid Carpenter matrix");ingredients=new Object[raw.length];for(int i=0;i<raw.length;i++)if(raw[i]!=null)ingredients[i]=raw[i] instanceof ItemStack?item((ItemStack)raw[i]):new ArrayList<>(members(raw[i]));}public int getWidth(){return width;}public int getHeight(){return height;}public Object[] getIngredients(){Object[] copy=new Object[ingredients.length];for(int i=0;i<copy.length;i++)copy[i]=ingredients[i]==null?null:ingredients[i] instanceof ItemStack?((ItemStack)ingredients[i]).copy():new ArrayList<>(members(ingredients[i]));return copy;}public boolean preserveNBT(){return false;}public ItemStack getRecipeOutput(){return result.copy();}public int getRecipeSize(){return ingredients.length;}public ItemStack getCraftingResult(InventoryCrafting inventory){return result.copy();}public boolean matches(IInventory inventory,net.minecraft.world.World world){return (Boolean)invoke(type("forestry.core.recipes.RecipeUtil"),null,"matches",new Class<?>[]{IDescriptiveRecipe.class,IInventory.class},this,inventory);}public boolean matches(InventoryCrafting inventory,net.minecraft.world.World world){return matches((IInventory)inventory,world);}}
}
